css:
.rsr-root[data-theme='concise'] { padding: 36px 44px; }
.rsr-root[data-theme='concise'] #resume { max-width: none; width: auto; }
.rsr-root[data-theme='concise'] .cross-heading { margin-top: 16px; }

.rsr-root[data-theme='concise'] {background: #fafafa;
	font: 15px "Open Sans", sans-serif;
	line-height: 1.4;
	position: relative;
	margin: 0;
	padding-bottom: 6rem;
	min-height: 100%; }
.rsr-root[data-theme='concise'] h1, .rsr-root[data-theme='concise'] h2, .rsr-root[data-theme='concise'] h3, .rsr-root[data-theme='concise'] h4, .rsr-root[data-theme='concise'] h5, .rsr-root[data-theme='concise'] h6 {font-family: "Lato", sans-serif;
	margin-bottom: 0.1rem; }
.rsr-root[data-theme='concise'] em {color: #999; }
.rsr-root[data-theme='concise'] p {line-height: 1.4;
	margin: 0.5rem 0; }
.rsr-root[data-theme='concise'] ul {margin-bottom: 0;
	list-style-type: '— '; }
.rsr-root[data-theme='concise'] section {margin-bottom: 1rem; }
.rsr-root[data-theme='concise'] blockquote {margin: 0;
	margin-bottom: 1em; }
.rsr-root[data-theme='concise'] .cross-heading {width: 100%;
	margin-top: 1.25em;
	text-align: center; }
.rsr-root[data-theme='concise'] .cross-heading > p {margin: 0;
	font-size:1.4rem;
	font-family: "Lato", sans-serif;
	text-transform: uppercase;
	display: inline-block;

	background: #fafafa;
	padding: 0 0.75em; }
.rsr-root[data-theme='concise'] .cross-heading::after {height: 1px;
	content: "";
	background: #aaa;
	width: 100%;
	display: block;
	position: relative;
	z-index: -100;
	top: -1em; }
.rsr-root[data-theme='concise'] .item {margin-bottom: 1em; }
.rsr-root[data-theme='concise'] .name {font-size: 1.1rem; }
.rsr-root[data-theme='concise'] .position, .rsr-root[data-theme='concise'] .title {font-size: 1.3rem; }
.rsr-root[data-theme='concise'] .section-container {padding: 0.25em;
	margin: 0.5em;
	margin-bottom: 1em; }
.rsr-root[data-theme='concise'] .section-container-hover {border-color: rgba(170, 170, 170, 255); }
.rsr-root[data-theme='concise'] .summary-section-dropdown-indicator {font-family: FontAwesome;
	font-size: 1.3rem;
	top: -0.5rem;
	position: relative;
	left: 50%;
	margin-left: -0.6rem; /* 1/2 of font-size */
	display: block;
	width: 0;
	height: 0; }
.rsr-root[data-theme='concise'] @keyframes bounce {0% {
		 top: -0.5rem; }
.rsr-root[data-theme='concise'] 50% {top: -0.1rem; }
.rsr-root[data-theme='concise'] 100% {top: -0.5rem; }
.rsr-root[data-theme='concise'] .summary-section-dropdown-hinter {font-family: FontAwesome;
	font-size: 1.3rem;
	top: -0.5rem;
	position: relative;
	left: 50%;
	margin-left: -0.6rem; /* 1/2 of font-size */
	display: block;
	width: 0;
	height: 0;

	animation: bounce 1.3s infinite;
	/*animation-timing-function: ease-in-out;*/ }
.rsr-root[data-theme='concise'] .concise-full-switch {text-align: center;
	font-size: 0.7rem;

	margin: 0;
	margin-top: 0.3rem; }
.rsr-root[data-theme='concise'] .concise-full-switch a {padding: 0.1rem; }
.rsr-root[data-theme='concise'] #header-container {margin: 0 auto;
	padding: 0; }
.rsr-root[data-theme='concise'] #header {border-bottom-style: solid;
	border-width: 1px;
	border-color: #aaa;
	text-align: center;
	margin: 0 auto;
	margin-bottom: 	0.75rem;
	margin-top: 		0.75rem;
	padding: 0.5em; }
.rsr-root[data-theme='concise'] #header h1 {font-size: 2.7em; }
.rsr-root[data-theme='concise'] #header h1, .rsr-root[data-theme='concise'] #header h2, .rsr-root[data-theme='concise'] #header h3, .rsr-root[data-theme='concise'] #header h4 {padding: 0;
	margin: 0.1rem; }
.rsr-root[data-theme='concise'] #resume {margin: 0 auto;
	/*max-width: 60%;*/
	/*padding: 0.25rem;*/ }
.rsr-root[data-theme='concise'] #basics {margin-bottom: -10px; }
.rsr-root[data-theme='concise'] #basics h3 {margin-top: 1.5em; }
.rsr-root[data-theme='concise'] #basics-header-container {overflow:hidden; }
.rsr-root[data-theme='concise'] #basics .full-section {margin: 0; }
.rsr-root[data-theme='concise'] #basics .summary {text-align: center; }
.rsr-root[data-theme='concise'] #contact {float: left;
	text-align: left; }
.rsr-root[data-theme='concise'] #location {float: right;
	text-align: right; }
.rsr-root[data-theme='concise'] #contact, .rsr-root[data-theme='concise'] #location {margin: 0;
	margin-bottom: 0.5rem; }
.rsr-root[data-theme='concise'] #profiles, .rsr-root[data-theme='concise'] #skills {overflow: hidden;
	margin: 0.5rem 0; }
.rsr-root[data-theme='concise'] #profiles .item, .rsr-root[data-theme='concise'] #skills .item {float: left;
	margin: 0.5rem 0.25rem; }
.rsr-root[data-theme='concise'] #skills .item {width: 33%; }
.rsr-root[data-theme='concise'] .keywords {margin: 0.1rem 0.25rem; }
.rsr-root[data-theme='concise'] .keyword {padding: 0.15rem 0.6rem;
	margin: 0.2rem 0.1rem;
	display: inline-block;

	color: #aaa;
	border-radius: 1rem;
	border-style: solid;
	border-width: 1px;
	border-color: #aaa; }
.rsr-root[data-theme='concise'] .reference {font-style: italic;
	font-size-adjust: 0.48; }
.rsr-root[data-theme='concise'] #footer {text-align: center;
	position: absolute;
	right: 0;
	bottom: 0;
	left: 0;
	padding: 1rem;
	font-size: smaller; }
